const raw = items[0] ?? {};
const state = $getWorkflowStaticData('global');
const payload = raw.json?.response ?? raw.json ?? {};
const error = raw.error ?? raw.json?.error ?? payload?.error;
const statusCode = Number(raw.json?.statusCode ?? payload?.statusCode ?? 0) || 0;
const failureThreshold = 2;
const checkUrl = '__OPS_PUBLIC_BASE_URL__/internal/market-api/api/v1/jobs/distribution-deadline-check';

function formatKst(value) {
  const date = value ? new Date(value) : new Date();
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Seoul',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  });
  const parts = Object.fromEntries(formatter.formatToParts(date).map((part) => [part.type, part.value]));
  return `${parts.year}. ${parts.month}. ${parts.day}. ${parts.hour}:${parts.minute} KST`;
}

function errorDetail() {
  if (typeof error === 'string' && error) return error;
  if (error?.message) return error.message;
  if (typeof payload?.detail === 'string' && payload.detail) return payload.detail;
  if (typeof raw.json?.message === 'string' && raw.json.message) return raw.json.message;
  if (typeof payload?.message === 'string' && payload.message) return payload.message;
  return 'unexpected response';
}

function classifyFailure(detail) {
  const text = String(detail ?? '');
  if (/EAI_AGAIN|EAIAGAIN|ENOTFOUND|getaddrinfo/i.test(text)) return 'NEOS 일정 조회 DNS 실패';
  if (/ECONNREFUSED|ECONNRESET|fetch failed/i.test(text)) return '배당 일정 조회 경로 연결 실패';
  if (/timed out|timeout/i.test(text)) return '배당 일정 조회 요청 시간 초과';
  if (/Failed to calculate distribution deadline signal/i.test(text)) return '배당 일정 계산 실패';
  return '배당 일정 조회 실패';
}

function failureMessage(detail, streak) {
  return [
    '배당 일정 조회 실패',
    `시각: ${formatKst()}`,
    `경로: ${checkUrl}`,
    `연속실패: ${streak}회`,
    `요약: ${classifyFailure(detail)}`,
    `세부: ${detail}`,
  ].join('\n');
}

function recoveryMessage() {
  return [
    '배당 일정 조회 복구',
    `시각: ${formatKst()}`,
    `경로: ${checkUrl}`,
    '요약: 배당 일정 조회와 계산 응답이 다시 정상화되었습니다.',
  ].join('\n');
}

const isFailure = Boolean(error)
  || statusCode >= 500
  || (typeof payload?.detail === 'string' && /Failed to calculate distribution deadline signal/i.test(payload.detail))
  || !Array.isArray(payload?.funds);

if (isFailure) {
  const detail = errorDetail();
  const streak = Number(state.transportFailureStreak ?? 0) + 1;
  state.transportFailureStreak = streak;
  if (streak < failureThreshold) {
    return [];
  }
  if (state.transportFailureAlerted === true) {
    return [];
  }
  state.transportFailureAlerted = true;
  return [{
    json: {
      message: failureMessage(detail, streak),
    },
  }];
}

const outputs = [];
if (state.transportFailureAlerted === true) {
  outputs.push({
    json: {
      message: recoveryMessage(),
    },
  });
}
state.transportFailureStreak = 0;
state.transportFailureAlerted = false;
return outputs;
